# SPDX-License-Identifier: MIT
"""Write the firmware's calibration table from the same data the simulator
uses: config/calibration.json and robot/joints.json."""
from __future__ import annotations

from pathlib import Path

from .protocol import ROOT, Calibration, load_calibration

TARGET = ROOT / "app_lab" / "microduck_agent" / "sketch" / "DuckTable.h"


def render(cal: Calibration) -> str:
    lines = ["// SPDX-License-Identifier: MIT",
             "// Generated by scripts/generate_description.py from config/calibration.json",
             "// and robot/joints.json. Do not edit: change those and regenerate.",
             "#pragma once", "", '#include "DuckControl.hpp"', "", "namespace duck {", "",
             "// name, pin, zero_deg, direction, min_deg, max_deg",
             "static const Table TABLE = {", "  {"]
    for j in cal.joints:
        lines.append(f'    {{"{j.name}", {j.pin}, {j.zero_deg!r}, {j.direction}, {j.min_deg!r}, {j.max_deg!r}}},  // {j.channel} {j.servo}')
    lines += ["  },",
              f"  {cal.min_us},  // min_us", f"  {cal.max_us},  // max_us", f"  {cal.frequency_hz},  // frequency_hz",
              f"  {cal.soft_start_pin},  // soft_start_pin", f"  {cal.max_speed_deg_s!r},  // max_speed_deg_s",
              f"  {cal.watchdog_ms},  // watchdog_ms",
              f"  {'true' if cal.watchdog_action == 'relax' else 'false'},  // watchdog_relax",
              f"  {cal.step_max_deg!r},  // step_max_deg",
              "  {" + ", ".join(repr(v) for v in cal.stand_deg) + "},  // stand_deg",
              "  // leg clearance, from robot/clearance.json: origins of the hip roll, hip pitch and knee",
              "  // frames, then thigh boxes and shin boxes as centre, half size, bounding radius (mm)",
              "  {"]
    for side in ("left", "right"):
        leg = (cal.clearance or {"legs": {side: {"origins_mm": [[0.0] * 3] * 3, "thigh": [], "shin": []}}})["legs"][side]
        lines.append(f"    {{  // {side}")
        lines.append("      {" + ", ".join("{" + ", ".join(repr(float(v)) for v in o) + "}" for o in leg["origins_mm"]) + "},")
        for part in ("thigh", "shin"):
            lines.append(f"      {len(leg[part])},  // {part} boxes")
            lines.append("      {")
            for box in leg[part]:
                lines.append("        {{" + ", ".join(repr(float(v)) for v in box) + "}},")
            lines.append("      },")
        lines.append("    },")
    lines += ["  },",
              "};", "", "}  // namespace duck", ""]
    return "\n".join(lines)


def write(path: Path | None = None) -> Path:
    path = path or TARGET
    path.write_text(render(load_calibration()), encoding="utf-8", newline="\n")
    return path
